Matching Ayahs
- = Alif, Laam, Miim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Abo ni bo bari mu nzira y’ukuri iva ku Muremyi wabo, kandi abo ni bo batsinze. 2:5; 31:5
- = Yemwe bene Isiraheli! Nibukeni umugisha Wanje nabahaye, n’ukuntu nabatonesheje abantu bose (ibiremwa vyose). 2:47; 2:122
- = Uwo muryango washize. Uwe ni uwo yakoze, n’iwanyu ni uwo mwakoze. Kandi ntimuzobazwa ibyo bakoze. 2:134; 2:141
- = Bazobamo ubuziraherezo. Ihabwa ntirizobabera ryoroheje, kandi ntibazarindirizwa. 2:162; 3:88
- = Usibye abizigama nyuma y’ivyo, bagatunganya imyitwarire yabo. Mu vy’ukuri, Allah ni Ubabarira, Nyene impuhwe. 3:89; 24:5
- = Ariko abahakanye kandi bakahakana ibimenyetso Vyacu – abo ni bo bantu bo mu muriro. 5:10; 5:86
- = Kandi nta kimenyetso kiba kikibagezeho mu bimenyetso vya Muremyi wabo, usibye ko bakivuga. 6:4; 36:46
- = Kandi mu vy’ukuri, intumwa zaronse isoni imbere y’uko uri, ariko abazisekaga bazengurutswe n’ivyo basekaga. 6:10; 21:41
- = Vuga ngo: “Mu vy’ukuri, ndatinya, nindishukira Muremyi wanje, ibihano vy’umusi ukomeye.” 6:15; 39:13
- = Nuko umutingito urabacakira, maze baratumbagurana mu ngo zabo, bapfuye. 7:78; 7:91
- = Nuko ajugunya inkoni yiwe, ihinduka inzoka igaragara. 7:107; 26:32
- = Nuko arambura ukuboko kwiwe, bugahinduka kwererana (gukabagirana) abareba. 7:108; 26:33
- = Baravuga bati: “Twemeye Muremyi w’ibiremwa vyose.” 7:121; 26:47
- = Muremyi wa Musa na Haruna. 7:122; 26:48
- = Kandi nzobaha akanya. Mu vy’ukuri, imigambi Yanje irakoze. 7:183; 68:45
- = Ni We wohereye Intumwa Yiwe irimwo ubuyobozi n’idini ry’ukuri, kugira ngo arigaragaze hejuru y’amadini yose, n’ubwo abagira ibanga ry’Allah babishaka. 9:33; 61:9
- = Yewe Muhanuzi! Rwanira abahakanyi n’indyarya, kandi ube ukare kuri bo. Aho bazokwibera ni umuriro wa Jahannama, kandi ni bubi bwo gusubira! 9:73; 66:9
- = Kandi baravuga bati: “Iyi ndagano izoba ryari, niba muri abanyakuri?” 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Kandi mu vy’ukuri twohereje Musa tumwehereje ibimenyetso Vyacu n’ububasha bugaragara. 11:96; 40:23
- = Kandi mu vy’ukuri twahaye Musa igitabo, ariko havuka amakimbirane kuri co. Iyo nta ndagano yabanje kugaruka iva kwa Muremyi wawe, ibyabo vyari guciroho iteka. Kandi mu vy’ukuri, barakishidikanya cane. 11:110; 41:45
- = Ivyo si ngombwa kuri Allah. 14:20; 35:17
- = “Ngiye kumutunganya, nkajugunamo umwuka Wanje, nuko mumugoramire musujudu.” 15:29; 38:72
